   441  void bn_read_bin(bn_t a, const uint8_t *bin, int len) {
   442          int i, j;
   443          dig_t d = (RLC_DIG / 8);
   444          int digs = (len % d == 0 ? len / d : len / d + 1);
   445
   446          bn_grow(a, digs);
   447          bn_zero(a);
   448          a->used = digs;
   449
   450          for (i = 0; i < digs - 1; i++) {
   451                  d = 0;
   452                  for (j = (RLC_DIG / 8) - 1; j >= 0; j--) {
   453                          d = d << 8;
   454                          d |= bin[len - 1 - (i * (RLC_DIG / 8) + j)];
   455                  }
   456                  a->dp[i] = d;
   457          }
   458          d = 0;
   459          for (j = (RLC_DIG / 8) - 1; j >= 0; j--) {
   460                  if ((int)(i * (RLC_DIG / 8) + j) < len) {
   461                          d = d << 8;
   462                          d |= bin[len - 1 - (i * (RLC_DIG / 8) + j)];
   463                  }
   464          }
   465          a->dp[i] = d;
   466
   467          a->sign = RLC_POS;
   468          bn_trim(a);
   469  }
